import{_ as t,d as r,e as a,y as i}from"./chunks/framework.D7CAgLCq.js";const u=JSON.parse('{"title":"Recovery with support is still recovery within its scope","description":"State the restored function, people, support conditions, and time window.","frontmatter":{"title":"Recovery with support is still recovery within its scope","description":"State the restored function, people, support conditions, and time window."},"headers":[],"relativePath":"en/concepts/recovery.md","filePath":"en/concepts/recovery.md"}'),s={name:"en/concepts/recovery.md"};function o(n,e,l,c,d,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="recovery-with-support-is-still-recovery-within-its-scope" tabindex="-1">Recovery with support is still recovery within its scope <a class="header-anchor" href="#recovery-with-support-is-still-recovery-within-its-scope" aria-label="Permalink to &quot;Recovery with support is still recovery within its scope&quot;">​</a></h1><p>A service can become genuinely available again through temporary power or continuing assistance. <strong>The support qualifies the recovery claim; its continued presence does not make the restored function unreal.</strong></p><h2 id="four-questions-belong-in-a-recovery-statement" tabindex="-1">Four questions belong in a recovery statement <a class="header-anchor" href="#four-questions-belong-in-a-recovery-statement" aria-label="Permalink to &quot;Four questions belong in a recovery statement&quot;">​</a></h2><p>What recovered? For whom? Under what support conditions? As of when? A working service point for its observed users does not establish coverage of all pre-disaster residents. Present availability does not establish that funding, staff rest, spare parts, or replacement arrangements will last through the next demand peak.</p><p>The book distinguishes restored output, target identity or function (K/F), and internal recovery margins. They can move at different speeds. External burdens matter as well: a service may recover while families take on additional travel, care, borrowing, or substitute work. Those costs should be investigated when relevant to the claim.</p><p>A later interruption needs explanation: continuing old damage, depleted reserves, lost support, a new shock, or a changed measurement boundary may have different implications. It does not automatically erase an earlier accurately bounded success. “False recovery” here concerns a claim exceeding its evidence, and does not by itself establish deception.</p><h2 id="gitlab-s-bounded-recovery" tabindex="-1">GitLab’s bounded recovery <a class="header-anchor" href="#gitlab-s-bounded-recovery" aria-label="Permalink to &quot;GitLab’s bounded recovery&quot;">​</a></h2><p>GitLab’s account of its January 2017 database outage records restored service after roughly eighteen hours alongside roughly six hours of unrecovered database changes. Service availability and data completeness therefore received different answers. At the report’s publication, some recovery arrangements were still being rebuilt or investigated. A more frequent snapshot schedule did not establish a new restoration duration. See the <a href="./../cases/gitlab-recovery.html">case and its source limits</a>.</p><h2 id="keep-the-original-target-visible" tabindex="-1">Keep the original target visible <a class="header-anchor" href="#keep-the-original-target-visible" aria-label="Permalink to &quot;Keep the original target visible&quot;">​</a></h2><p>Completing a task with assistance, transferring a skill independently after support is removed, and improving a person’s later life are different targets. If the task was supported participation, success does not require subsequently withdrawing necessary support. If the target was independent transfer, it needs a suitable separate assessment.</p><p>Repair need not reverse time or recreate every past component. It seeks a new state meeting the declared target criteria; the desirability of the target, the distribution of costs, and permission to act remain separate questions.</p><p>Read <a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-6">§6.6</a>, <a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-10">§6.10</a>, <a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-10-1">§6.10.1</a>, and <a href="/xi-kari-skill/handbook/en/theory/appendix-d/d-31.html#section-d-31">D.31</a>.</p>',12)])])}const v=t(s,[["render",o]]);export{u as __pageData,v as default};
